mkdir -p "$SP" && cat > "$SP/tb_sbox.v" <<'EOF'
`timescale 1ns/1ps
module tb;
  reg [10:0] raddr;
  wire [15:0] rdata;
  reg clk=0;
  integer a;
  reg [7:0] addr8;
  SB_RAM40_4K #(
    .READ_MODE(1), .WRITE_MODE(1),
    .INIT_0(256'h85c4d834ef22d4b989d975ce78ebd3405fa9d7fe2f53040695f36fc62fdf2de9),
    .INIT_1(256'h4dae5f63ca800319a219922c878382b2042fa4cdccdb8c36e5f52f3e4b25edbf),
    .INIT_2(256'hb2e631e07d1eb7c2668faca8a8a281cf95319e83cb5e2b4e99443ba536189203),
    .INIT_3(256'hc7cdaaae5946de3c9caee12ea2628a47f915286c2baaa8db852721e3ff8aeae6),
    .INIT_4(256'hb38b73fc542cabf0e0042f00b1f984421a8f24fa3d7eca72027a937fa9a57071),
    .INIT_5(256'h75102ed9eed416f8b952d0bb2db7e5d16cdac02f5e90c3ca24b8126137044e48),
    .INIT_6(256'hb23dc192a95f0c6b677412424eb52e6cf301b96b267ef4eac6b49a342e317d8c),
    .INIT_7(256'h572d44ac3633a04b29c0dfb57023d812b6aa51fae993732dd138b4cb500eecc9)
  ) u (
    .RADDR(raddr), .RDATA(rdata),
    .WADDR(11'b0), .MASK(16'b0), .WDATA(16'b0),
    .WE(1'b0), .WCLKE(1'b1), .WCLK(clk),
    .RE(1'b1), .RCLKE(1'b1), .RCLK(clk)
  );
  initial begin
    for (a=0; a<256; a=a+1) begin
      addr8 = a[7:0];
      // design maps: RADDR = {2'b0, addr8[7], 1'b0, addr8[6:0]}
      raddr = {2'b0, addr8[7], 1'b0, addr8[6:0]};
      #1 clk=1; #1 clk=0; #1;
      // data on even bit positions: rdata[14,12,10,8,6,4,2,0] = bits7..0
      $display("%0d %0d", a,
        {rdata[14],rdata[12],rdata[10],rdata[8],rdata[6],rdata[4],rdata[2],rdata[0]});
    end
    $finish;
  end
endmodule
EOF
source /opt/oss-cad-suite/environment 2>/dev/null
CELLS=/opt/oss-cad-suite/share/yosys/ice40/cells_sim.v
iverilog -g2012 -o "$SP/tb_sbox.vvp" -DNO_ICE40_DEFAULT_ASSIGNMENTS "$CELLS" "$SP/tb_sbox.v" 2>&1 | head -20
vvp "$SP/tb_sbox.vvp" 2>/dev/null > "$SP/sbox_even.txt"
echo "lines: $(wc -l < "$SP/sbox_even.txt")"; head -8 "$SP/sbox_even.txt"; echo ...; tail -4 "$SP/sbox_even.txt"

